public sealed class Order
{
    private readonly List<OrderLine> _lines = new List<OrderLine>();

    public Guid Id { get; }
    public OrderStatus Status { get; private set; }

    public Order(Guid id)
    {
        Id = id;
        Status = OrderStatus.Draft;
    }

    public void AddLine(ProductId productId, decimal unitPrice, int quantity)
    {
        if (Status != OrderStatus.Draft)
        {
            throw new InvalidOperationException("Placed orders cannot be edited.");
        }

        _lines.Add(new OrderLine(productId, unitPrice, quantity));
    }

    public void Place()
    {
        if (_lines.Count == 0)
        {
            throw new InvalidOperationException("An empty order cannot be placed.");
        }

        if (Status != OrderStatus.Draft)
        {
            throw new InvalidOperationException("Only a draft order can be placed.");
        }

        Status = OrderStatus.Placed;
    }
}

