        if self.status is not OrderStatus.DRAFT:
            raise ValueError("placed orders cannot be edited")
        self._lines.append(OrderLine(product_id, unit_price, quantity))

    def place(self):
        if len(self._lines) == 0:
            raise ValueError("an empty order cannot be placed")
        if self.status is not OrderStatus.DRAFT:
            raise ValueError("only a draft order can be placed")
        self.status = OrderStatus.PLACED

