public interface IOrderStore
{
    Task<Order?> LoadAsync(Guid orderId, CancellationToken cancellationToken);
    Task SaveAsync(Order order, CancellationToken cancellationToken);
}

// SQL adapter owned by infrastructure.
public sealed class SqlOrderStore : IOrderStore
{
    private readonly DbConnection _connection;

    public SqlOrderStore(DbConnection connection)
    {
        _connection = connection;
    }

    public async Task<Order?> LoadAsync(
        Guid orderId,
        CancellationToken cancellationToken)
    {
        DbRow? row = await QueryOrderRowAsync(orderId, cancellationToken);
        if (row is null)
        {
            return null;
        }

        return MapToDomain(row);
    }

    public async Task SaveAsync(
        Order order,
        CancellationToken cancellationToken)
    {
        await WriteOrderRowAsync(order, cancellationToken);
    }
}

